#!/usr/bin/env python3
"""Improved pty driver.

Usage:
  python3 /tmp/ptydrv2.py --cmd 'CMD' [--send 'bytes-with-escapes'] [--delay 0.3]
        [--env K=V ...] [--term xterm] [--timeout 8] [--rows 24] [--cols 80]
        [--sep]  # send each --send arg separately with delay between

Prints:
  raw output repr, then exit status info.
"""
import argparse, os, pty, select, sys, time, errno, signal, fcntl, termios, struct

p = argparse.ArgumentParser()
p.add_argument('--cmd', required=True)
p.add_argument('--send', action='append', default=[])
p.add_argument('--delay', type=float, default=0.35)
p.add_argument('--predelay', type=float, default=0.5)
p.add_argument('--env', action='append', default=[])
p.add_argument('--term', default='xterm-256color')
p.add_argument('--timeout', type=float, default=8.0)
p.add_argument('--rows', type=int, default=24)
p.add_argument('--cols', type=int, default=80)
p.add_argument('--noeof', action='store_true', help="don't send EOF at end")
p.add_argument('--annotate', action='store_true', help='print output chunk by chunk with markers')
a = p.parse_args()

env = dict(os.environ)
env['TERM'] = a.term
for kv in a.env:
    k, _, v = kv.partition('=')
    env[k] = v

pid, fd = pty.fork()
if pid == 0:
    os.execvpe('/bin/sh', ['/bin/sh', '-c', a.cmd], env)
    os._exit(127)

# set window size
fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', a.rows, a.cols, 0, 0))

chunks = []  # list of ('out', bytes) or ('in', bytes)
start = time.time()


def drain(dur):
    end = time.time() + dur
    while True:
        rem = end - time.time()
        if rem <= 0:
            break
        try:
            r, _, _ = select.select([fd], [], [], rem)
        except OSError:
            break
        if not r:
            continue
        try:
            d = os.read(fd, 65536)
        except OSError:
            return False
        if not d:
            return False
        chunks.append(('out', d))
    return True


alive = drain(a.predelay)
for s in a.send:
    b = s.encode('utf-8').decode('unicode_escape').encode('latin-1')
    try:
        os.write(fd, b)
    except OSError:
        break
    chunks.append(('in', b))
    if not drain(a.delay):
        alive = False
        break

if alive and not a.noeof:
    # send EOF by closing? Use ^D char
    pass

# final drain
if alive:
    drain(min(a.timeout, 2.0))

try:
    os.close(fd)
except OSError:
    pass
try:
    wpid, status = os.waitpid(pid, 0)
except ChildProcessError:
    status = None

if a.annotate:
    for kind, d in chunks:
        print(('IN : ' if kind == 'in' else 'OUT: ') + repr(d))
else:
    print(repr(b''.join(d for k, d in chunks if k == 'out')))

if status is None:
    print('STATUS: unknown')
elif os.WIFEXITED(status):
    print('EXITCODE:', os.WEXITSTATUS(status))
elif os.WIFSIGNALED(status):
    print('SIGNAL:', os.WTERMSIG(status))
else:
    print('STATUS:', status)
